dataModel.source:
type DeviceStatus = "online" | "offline" | "warning";

interface Device {
  id: string;
  name: string;
  model: string;
  status: DeviceStatus;
  ipAddress: string;
  firmware: string;
}

interface DeviceSettings {
  deviceId: string;
  network: { dhcp: boolean; ip: string; subnet: string; gateway: string };
  thresholds: { temperatureMax: number; cpuMax: number };
  pollingIntervalSec: number;
}

interface Metric {
  deviceId: string;
  timestamp: string;
  temperature: number;
  cpu: number;
  trafficMbps: number;
}

interface Alarm {
  id: string;
  deviceId: string;
  level: "info" | "warn" | "error";
  message: string;
  occurredAt: string;
  acknowledged: boolean;
}
